INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-MA-001-31', 'Stage 4', '수학', 'Number and Algebra', 'Integer Operations', 2, 'Skill', 'Original practice - NSW Curriculum Stage 4', 60, '기온이 아침에 -3°C였고 정오까지 8°C 올랐습니다. 정오 기온은 몇 도일까요? A) -11°C B) -5°C C) 5°C D) 11°C', 'The temperature was -3°C in the morning and rose by 8°C by noon. What was the temperature at noon? A) -11°C B) -5°C C) 5°C D) 11°C', 'Adding integers', 'Number line', 'C', '-3 + 8 = 5이므로 정오 기온은 5°C입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-MA-002-32', 'Stage 4', '수학', 'Number and Algebra', 'Fractions and Decimals', 2, 'Skill', 'Original practice - NSW Curriculum Stage 4', 60, '리본 2.4m 중 3/5을 사용했습니다. 사용한 리본은 몇 m일까요? A) 0.8m B) 1.2m C) 1.44m D) 1.8m', 'A student uses 3/5 of a 2.4 m ribbon. How much ribbon is used? A) 0.8 m B) 1.2 m C) 1.44 m D) 1.8 m', 'Fraction of a quantity', 'Multiply by a fraction', 'C', '2.4 × 3/5 = 7.2/5 = 1.44m입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-MA-003-33', 'Stage 4', '수학', 'Number and Algebra', 'Algebraic Expressions', 2, 'Skill', 'Original practice - NSW Curriculum Stage 4', 60, '연필 p자루가 든 상자 4개와 낱개 연필 3자루가 있습니다. 전체 연필 수를 나타내는 식은 무엇일까요? A) 4p + 3 B) 4 + 3p C) 7p D) 4p - 3', 'There are 4 boxes with p pencils in each box, plus 3 loose pencils. Which expression gives the total number of pencils? A) 4p + 3 B) 4 + 3p C) 7p D) 4p - 3', 'Forming algebraic expressions', 'Multiplication and addition', 'A', '상자 4개에 든 연필은 4p자루이고 낱개 3자루를 더하므로 4p + 3입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-MA-004-34', 'Stage 4', '수학', 'Measurement and Space', 'Area', 2, 'Skill', 'Original practice - NSW Curriculum Stage 4', 60, '직사각형 정원의 길이는 9m, 너비는 4m입니다. 넓이는 얼마일까요? A) 13m² B) 26m² C) 36m² D) 72m²', 'A rectangular garden is 9 m long and 4 m wide. What is its area? A) 13 m² B) 26 m² C) 36 m² D) 72 m²', 'Area of a rectangle', 'Length × width', 'C', '직사각형의 넓이는 길이 × 너비이므로 9 × 4 = 36m²입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-MA-005-35', 'Stage 4', '수학', 'Statistics and Probability', 'Probability', 3, 'Ability', 'Original practice - NSW Curriculum Stage 4', 75, '주머니에 빨간 구슬 3개, 파란 구슬 2개, 초록 구슬 5개가 있습니다. 무작위로 한 개를 꺼낼 때 파란 구슬일 확률은? A) 1/5 B) 1/3 C) 2/5 D) 1/2', 'A bag contains 3 red, 2 blue and 5 green counters. What is the probability of randomly drawing a blue counter? A) 1/5 B) 1/3 C) 2/5 D) 1/2', 'Experimental and theoretical probability', 'Favourable outcomes over total outcomes', 'A', '전체 구슬은 10개이고 파란 구슬은 2개이므로 확률은 2/10 = 1/5입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-SC-001-36', 'Stage 4', '과학', 'Forces', 'Friction', 2, 'Skill', 'Original practice - NSW Science 7-10 Stage 4', 60, '같은 장난감 자동차를 서로 다른 표면에서 굴리는 실험에서 표면의 거칠기가 이동 거리에 미치는 영향을 알아보려 합니다. 공정한 실험을 위해 반드시 같게 유지해야 할 것은? A) 표면 재료 B) 자동차를 놓는 출발 높이 C) 바닥의 질감 D) 이동 거리', 'A student tests how surface roughness affects how far the same toy car travels. Which variable should be kept the same for a fair test? A) The surface material B) The release height of the car C) The surface texture D) The distance travelled', 'Working scientifically', 'Control variables', 'B', '표면 재료와 질감은 바꾸어 시험할 변수입니다. 출발 높이를 일정하게 해야 표면의 영향만 공정하게 비교할 수 있습니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-SC-002-37', 'Stage 4', '과학', 'Cells and Classification', 'Cell Structures', 2, 'Skill', 'Original practice - NSW Science 7-10 Stage 4', 60, '식물 세포에서 광합성이 주로 일어나는 구조는 무엇일까요? A) 세포막 B) 엽록체 C) 핵 D) 세포질', 'Which structure is the main site of photosynthesis in a plant cell? A) Cell membrane B) Chloroplast C) Nucleus D) Cytoplasm', 'Cells and classification', 'Cell structures and functions', 'B', '엽록체의 엽록소가 빛 에너지를 흡수해 광합성을 돕습니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-SC-003-38', 'Stage 4', '과학', 'Solutions and Mixtures', 'Separating Mixtures', 2, 'Skill', 'Original practice - NSW Science 7-10 Stage 4', 60, '모래와 물이 섞인 혼합물에서 모래를 분리하는 가장 적절한 방법은? A) 여과 B) 증류 C) 자석으로 분리 D) 크로마토그래피', 'Which method is most suitable for separating sand from a mixture of sand and water? A) Filtration B) Distillation C) Magnetic separation D) Chromatography', 'Solutions and mixtures', 'Choose a separation method by material properties', 'A', '모래는 물에 녹지 않는 고체이므로 여과지에 걸러 분리할 수 있습니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-SC-004-39', 'Stage 4', '과학', 'Observing the Universe', 'Earth and Moon', 2, 'Ability', 'Original practice - NSW Science 7-10 Stage 4', 60, '달의 모양이 한 달 동안 달라져 보이는 주된 이유는 무엇일까요? A) 지구의 그림자가 매일 달을 가려서 B) 달이 지구 주위를 공전하며 햇빛을 받는 면이 다르게 보이므로 C) 달이 스스로 빛을 내며 밝기가 변하므로 D) 구름이 달의 일부를 가리므로', 'Why does the Moon appear to change shape over about a month? A) Earth''s shadow covers it each day B) As the Moon orbits Earth, we see different portions of its sunlit half C) The Moon makes its own light and changes brightness D) Clouds cover part of the Moon', 'Observing the Universe', 'Model the Sun-Earth-Moon system', 'B', '달은 태양빛을 반사하고, 지구 주위를 공전하면서 우리가 보는 밝은 면의 비율이 달라집니다. 지구 그림자가 원인인 것은 월식입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-EN-001-40', 'Stage 4', '영어', 'Reading and Viewing', 'Inference', 2, 'Ability', 'Original practice - NSW English 7-10 Stage 4', 60, '다음 글을 읽으세요: “Mina checked the dark clouds, zipped her jacket and placed an umbrella in her bag before leaving.” 가장 타당한 추론은 무엇일까요? A) Mina는 수영하러 간다 B) 비가 올 가능성에 대비한다 C) 날씨가 매우 덥다 D) Mina는 우산을 잃어버렸다', 'Read: “Mina checked the dark clouds, zipped her jacket and placed an umbrella in her bag before leaving.” What is the best inference? A) Mina is going swimming B) She is preparing for possible rain C) The weather is very hot D) Mina has lost her umbrella', 'Comprehension', 'Make an inference using textual clues', 'B', '짙은 구름을 확인하고 재킷을 입은 뒤 우산을 챙긴 행동은 비가 올 가능성에 대비한다는 추론을 뒷받침합니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-EN-002-41', 'Stage 4', '영어', 'Language and Literature', 'Figurative Language', 2, 'Skill', 'Original practice - NSW English 7-10 Stage 4', 60, '“The wind whispered through the trees.”에서 사용된 표현법은 무엇일까요? A) 직유법 B) 의인법 C) 과장법 D) 두운법', 'Which technique is used in “The wind whispered through the trees”? A) Simile B) Personification C) Hyperbole D) Alliteration', 'Language forms and features', 'Identify figurative language', 'B', '속삭이는 행동은 사람의 행동입니다. 바람에 사람의 행동을 부여했으므로 의인법(personification)입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-EN-003-42', 'Stage 4', '영어', 'Writing', 'Audience and Purpose', 2, 'Ability', 'Original practice - NSW English 7-10 Stage 4', 60, '학교 교장에게 점심시간에 그늘막을 설치해 달라고 요청하는 글에서 가장 설득력 있는 근거는 무엇일까요? A) 그늘막은 파란색일 수 있다 B) 더 많은 학생이 햇볕을 피하고 야외 공간을 안전하게 이용할 수 있다 C) 점심시간은 하루 중간에 있다 D) 운동장은 이미 존재한다', 'A student writes to the principal requesting a shaded area for lunch. Which reason is the strongest support? A) The shade structure could be blue B) More students could avoid strong sun and use the outdoor area safely C) Lunch happens in the middle of the day D) The school already has a playground', 'Creating written texts', 'Select relevant evidence for audience and purpose', 'B', '요청의 목적과 직접 관련되고 학생들에게 주는 실질적 이점을 제시하는 B가 가장 설득력 있는 근거입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-EN-004-43', 'Stage 4', '영어', 'Language and Literature', 'Vocabulary in Context', 2, 'Skill', 'Original practice - NSW English 7-10 Stage 4', 45, '문장에서 밑줄 친 단어의 뜻을 문맥으로 추론하세요: “After weeks without rain, the soil was **parched** and cracked.” parched의 뜻은? A) 물에 잠긴 B) 매우 건조한 C) 얼어붙은 D) 비옥한', 'Use context to work out the meaning of the bold word: “After weeks without rain, the soil was **parched** and cracked.” What does “parched” mean? A) Flooded B) Extremely dry C) Frozen D) Fertile', 'Comprehension', 'Use context to infer word meaning', 'B', '비가 오지 않았고 땅이 갈라졌다는 단서로 보아 parched는 매우 건조하다는 뜻입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-TS-001-44', 'Stage 4', 'Thinking Skill', 'Number Patterns', 'Recursive Rule', 2, 'Skill', 'Original practice - NSW Curriculum Stage 4', 45, '수열 4, 7, 13, 25, ...에서 각 항은 앞 항에 같은 규칙을 적용해 만들어집니다. 다음 항은? A) 37 B) 43 C) 49 D) 51', 'In the sequence 4, 7, 13, 25, ... each term follows the same rule from the previous term. What is the next term? A) 37 B) 43 C) 49 D) 51', 'Recognise and apply a recursive rule', 'Multiply by 2, then subtract 1', 'C', '각 항에 2를 곱하고 1을 빼면 다음 항이 됩니다. 25 × 2 - 1 = 49입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-TS-002-45', 'Stage 4', 'Thinking Skill', 'Logical Reasoning', 'Deduction', 2, 'Skill', 'Original practice - NSW Curriculum Stage 4', 60, '모든 현장 조사(field study)는 야외 활동입니다. 오늘 활동은 현장 조사였습니다. 반드시 참인 결론은? A) 오늘의 모든 야외 활동은 현장 조사였다 B) 오늘 활동은 야외에서 이루어졌다 C) 현장 조사는 모두 과학 수업이다 D) 오늘 비가 오지 않았다', 'All field studies are outdoor activities. Today''s activity was a field study. Which conclusion must be true? A) All outdoor activities today were field studies B) Today''s activity took place outdoors C) All field studies are science lessons D) It did not rain today', 'Deductive reasoning', 'Distinguish a statement from its converse', 'B', '현장 조사는 모두 야외 활동이고 오늘 활동은 현장 조사이므로, 오늘 활동은 야외에서 이루어졌습니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-TS-003-46', 'Stage 4', 'Thinking Skill', 'Data Science', 'Interpret a Table', 2, 'Skill', 'Original practice - NSW Science 7-10 Stage 4', 60, '같은 높이에서 공을 떨어뜨린 결과가 표와 같습니다: 표면 A 3회 반발 높이(cm)=42, 40, 41; 표면 B=28, 30, 29. 무엇을 가장 타당하게 결론 내릴 수 있을까요? A) 표면 A에서 평균 반발 높이가 더 크다 B) 표면 B가 공을 더 높게 튕긴다 C) 표면 A의 모든 측정값은 42이다 D) 표면 종류는 결과에 영향을 주지 않는다', 'A ball is dropped from the same height. Rebound heights (cm): Surface A: 42, 40, 41; Surface B: 28, 30, 29. Which conclusion is best supported? A) The mean rebound height is greater on Surface A B) The ball rebounds higher on Surface B C) Every Surface A result is 42 D) Surface type has no effect', 'Data science', 'Compare repeated measurements', 'A', 'A의 평균은 41cm이고 B의 평균은 29cm이므로 A에서 평균 반발 높이가 더 큽니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-TS-004-47', 'Stage 4', 'Thinking Skill', 'Classification', 'Identify the Odd One Out', 2, 'Skill', 'Original practice - NSW Science 7-10 Stage 4', 45, '다음 중 나머지와 분류 기준이 다른 하나는? A) 철 B) 구리 C) 알루미늄 D) 산소', 'Which one does not fit the same classification as the others? A) Iron B) Copper C) Aluminium D) Oxygen', 'Classification', 'Compare material categories', 'D', '철, 구리, 알루미늄은 금속 원소이고 산소는 비금속 원소입니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-TA-001-48', 'Stage 4', 'Thinking Ability', 'Experimental Design', 'Evaluate Evidence', 3, 'Ability', 'Original practice - NSW Science 7-10 Stage 4', 75, '식물이 빛을 더 많이 받으면 더 빨리 자란다는 가설을 시험합니다. 가장 신뢰할 수 있는 방법은? A) 햇빛 아래 식물 한 개만 관찰한다 B) 여러 식물을 서로 다른 빛 조건에서 키우고 물·토양·종은 같게 한 뒤 높이를 반복 측정한다 C) 빛과 물의 양을 동시에 바꾸고 한 번 측정한다 D) 자란 식물의 사진만 비교한다', 'A student tests the hypothesis that more light makes plants grow faster. Which method provides the most reliable evidence? A) Observe one plant in sunlight B) Grow several plants under different light levels, keep water, soil and species the same, and measure height repeatedly C) Change light and water together and measure once D) Compare photographs only', 'Working scientifically', 'Control variables and repeat measurements', 'B', '여러 식물을 사용하고 다른 조건을 통제하며 반복 측정하면 빛의 영향에 대한 더 신뢰할 수 있는 증거를 얻습니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-TA-002-49', 'Stage 4', 'Thinking Ability', 'Problem Solving', 'Choose an Efficient Strategy', 3, 'Ability', 'Original practice - NSW Curriculum Stage 4', 60, '학교 공연 티켓은 성인 12달러, 학생 7달러입니다. 성인 3명과 학생 8명이 살 때 총액을 구하는 가장 효율적인 식은? A) 3 × (12 + 7) + 8 B) 3 × 12 + 8 × 7 C) (3 + 8) × 12 D) 3 + 12 + 8 + 7', 'A school performance ticket costs $12 for an adult and $7 for a student. Which expression efficiently finds the cost for 3 adults and 8 students? A) 3 × (12 + 7) + 8 B) 3 × 12 + 8 × 7 C) (3 + 8) × 12 D) 3 + 12 + 8 + 7', 'Problem solving', 'Represent and solve a multi-step situation', 'B', '성인 티켓은 3 × 12달러, 학생 티켓은 8 × 7달러이므로 두 금액을 더하는 식이 맞습니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-TA-003-50', 'Stage 4', 'Thinking Ability', 'Proportional Reasoning', 'Scale a Recipe', 3, 'Ability', 'Original practice - NSW Curriculum Stage 4', 60, '레시피는 4인분에 쌀 300g을 사용합니다. 같은 비율로 10인분을 만들 때 필요한 쌀은? A) 600g B) 700g C) 750g D) 900g', 'A recipe uses 300 g of rice for 4 servings. How much rice is needed for 10 servings at the same rate? A) 600 g B) 700 g C) 750 g D) 900 g', 'Ratio and rates', 'Scale a quantity proportionally', 'C', '1인분당 300 ÷ 4 = 75g이므로 10인분에는 75 × 10 = 750g이 필요합니다.');
INSERT OR REPLACE INTO problems (id, stage, subject, topic, subtype, difficulty, skill_type, source, time_sec, q_kr, q_en, rule1, rule2, answer, explanation_kr) 
VALUES ('S4-TA-004-51', 'Stage 4', 'Thinking Ability', 'Scientific Reasoning', 'Interpret a Model', 3, 'Ability', 'Original practice - NSW Science 7-10 Stage 4', 75, '학생이 낮과 밤을 설명하려고 손전등을 지구본에 비춥니다. 이 모형에서 손전등은 무엇을 나타내며, 지구본을 회전시키는 이유는 무엇일까요? A) 손전등은 달이고 지구본 회전은 계절을 나타낸다 B) 손전등은 태양이며 지구 자전으로 낮과 밤이 번갈아 나타난다 C) 손전등은 별이며 지구 공전으로 달의 위상이 생긴다 D) 손전등은 지구이며 지구본 회전은 조석을 나타낸다', 'A student shines a torch on a globe to model day and night. What does the torch represent, and why is the globe rotated? A) The Moon; rotation models seasons B) The Sun; Earth''s rotation brings places into and out of daylight C) A star; Earth''s orbit causes Moon phases D) Earth; rotation models tides', 'Scientific models', 'Relate model components to the real system', 'B', '손전등은 태양을, 지구본은 지구를 나타냅니다. 지구의 자전으로 한쪽은 빛을 받아 낮이 되고 반대쪽은 밤이 됩니다.');